  if (!up && e.immune) { e.immune = false; W.toast('☂ Зонтики сбиты! Зурга без защиты!'); W.say('<b>Зурга:</b> Мои зонтики! Это был подарок от мамы!'); }
  if (up && !e.immune) e.immune = true;
  const sp = e.t.sp * (e.slowK || 1); if (d > 20) { e.vx += (dx / d * sp - e.vx) * dt * 2; e.vz += (dz / d * sp - e.vz) * dt * 2; } else { e.vx *= 1 - dt * 2; e.vz *= 1 - dt * 2; }
  e.tp = (e.tp || 2) - dt; if (e.tp <= 0 && d < 60) { e.tp = up ? 2.6 : 2.4; W.enemyShoot(e, 26, 6); if (!up) { setTimeout(() => !e.dead && !W.paused && W.enemyShoot(e, 28, 6), 250); } if (Math.random() < 0.25) W.say(pick(['<b>Зурга:</b> Получи чайник!', '<b>Зурга:</b> Это вам не варенье!', '<b>Зурга:</b> Я в молодости метала чайники за сборную Ксар-Талы!'])); }
  e.pc = (e.pc || 14) - dt; if (e.pc <= 0) { e.pc = 22; if (W.EN.filter((q) => !q.dead && q.type === 'police').length < 3) for (let k = 0; k < 2; k++) W.spawn('police', e.x + rnd(-10, 10), e.z + rnd(-10, 10), { ai: policeAI }); W.say('<b>Зурга:</b> Полиция! Взять эту бабку!'); }
