  if (e.ph2 === 'under') { e.immune = true; e.jy = -12; e.x = e.at.x; e.z = e.at.z; if (e.tt <= 0) { const near = Hs.filter((h) => h !== e.at).sort((a, b) => Math.hypot(a.x - R.x, a.z - R.z) - Math.hypot(b.x - R.x, b.z - R.z)); e.to = Math.random() < (rage ? 0.8 : 0.6) ? near[0] : pick(near); e.to.rim.material.color.set('#ff4a3a'); e.ph2 = 'jump'; e.tt = e.dur = rage ? 2.1 : 2.7; e.shot = 0; burst(W.scene, e.at.x, W.H(e.at.x, e.at.z) + 1, e.at.z, 'smoke', '#bfe8ff', 10, 1.2); sfx('boom', { vol: 0.4 }); e.immune = false; } }
