function waves10Step(dt) { const A = W.waves10 || []; for (let i = A.length - 1; i >= 0; i--) { const q = A[i]; q.r += 24 * dt; q.m.scale.setScalar(q.r); q.m.material.opacity = 0.85 * (1 - q.r / 32); const d = Math.hypot(R.x - q.x, R.z - q.z); if (!q.hit && Math.abs(d - q.r) < 1.6 && R.air <= 0) { q.hit = true; W.hurt(13, 'ледяная волна'); R.vy = 4; R.air = 1; } if (q.r > 32) { W.scene.remove(q.m); A.splice(i, 1); } } }
