/* ---------- конец главы, конец экспедиции ---------- */
function chapterEnd() { sfx('j_win3'); confetti();
  if (W.ch === 1) { W.flags.ch1 = 1; save(); titleCard('ГЛАВА 1 ПРОЙДЕНА', 'Колян повержен!', 'Пираты разбежались, колония празднует. Но в лагере Коляна нашлась накладная: огород бабы Тани продан пиратам «ТрансГалактик», и баржа увозит его через Долины Маринер — в Ксар-Талу, город марсиан.', '▶ Глава 2: в каньон', () => goChapter(2)); return; }
  if (W.ch === 2) { W.flags.ch2 = 1; save(); titleCard('ГЛАВА 2 ПРОЙДЕНА', 'Баржа рухнула!', 'Огород бабы Тани вылетел из трюма и… улетел дальше, на парашюте, прямо в Ксар-Талу. Пип говорит, у марсиан за такое — либо орден, либо тёща.', '▶ Глава 3: Ксар-Тала', () => goChapter(3)); return; }
  if (W.ch === 4) { W.flags.ch4 = 1; save(); titleCard('ГЛАВА 4 ПРОЙДЕНА', 'Червь отрыгнул огород!', 'Червь-картофелеед икнул — и выплюнул огород бабы Тани целиком, даже с пугалом. Гномы на радостях подняли его наверх в клети. Но огород сохнет: на Марсе нет воды.<br><br>Пип говорит: вода есть — во льду Северной полярной шапки. Там медведи, северное сияние и… кто-то ещё.', '▶ Глава 5: Полярная шапка', () => goChapter(5)); return; }
  if (W.ch === 3) { W.flags.ch3 = 1; save(); titleCard('ГЛАВА 3 ПРОЙДЕНА', 'Чай у тёщи', 'Зурга сдалась, разлила чай и всплакнула: огород ей очень нравился. Баба Таня оставила ей рассаду и рецепт пирожков.<br><br>Но тут кратер-смайлик снова засмеялся. Марсотрясение! Земля под дворцом треснула, и огород провалился вниз — в Кристальные пещеры…', '▶ Глава 4: Кристальные пещеры', () => goChapter(4)); return; }
  if (W.ch === 5) { W.flags.ch5 = 1; save(); titleCard('ГЛАВА 5 ПРОЙДЕНА', 'Дракон растаял!', 'Ледяной дракон рассыпался облаком пара и пролился дождём — первым настоящим дождём на Марсе за миллионы лет. Медведи принесли вёдра, гномы — бочки, и огород бабы Тани наконец полили.<br><br>Но столб пара над полюсом увидели с орбиты. С Фобоса, где стоит флагман пиратов «ТрансГалактик», пришло сообщение: «Бабка. Огород. Космопорт. Завтра».', '▶ Глава 6: Фобос-Узловая', () => goChapter(6)); return; }
  if (W.ch === 6) { W.flags.ch6 = 1; save(); titleCard('ГЛАВА 6 ПРОЙДЕНА', 'Флагман пал!', 'Адмирал Галина сдалась и улетела к сыновьям на спасательной шлюпке — воспитывать. Трюм открылся: огород бабы Тани цел, и даже картошка из невесомости вернулась на грядку.<br><br>Но флагман потерял двигатели и начал падать — прямо на Марс, на склон Олимпа, самого высокого вулкана Солнечной системы. С огородом на борту. А Олимп, говорят, не любит гостей…', '▶ Глава 7: Олимп', () => goChapter(7)); return; }
  if (W.ch === 7) { finale(); return; }
  if (W.ch === 8) { W.flags.ch8 = 1; stepI = STEPSC.length; W.ckpt = null; W.obj = { text: 'Свободная езда по Церере' }; save(); titleCard('ГЛАВА 8 ПРОЙДЕНА', 'Лёд — гномам!', 'Камнедробилка Толяна развалилась, и лёд вернулся в шахту «Ледяная». Гномы залили тарелке полный бак и подарили деду бороду — почётную, на резинке.<br><br>Следующая пересадка — Венера: облака из кислоты, города на воздушных шарах и… очень жаркие мамаши.', '▶ Глава 9: Венера', () => goChapter(9)); return; }
  if (W.ch === 9) { W.flags.ch9 = 1; stepI = STEPSC.length; W.ckpt = null; W.obj = { text: 'Свободная езда по Венере' }; save(); titleCard('ГЛАВА 9 ПРОЙДЕНА', 'Газ — городу!', 'Дирижабль мамаши Зины сдулся и мягко сел на причал. Зина посмотрела на сыновей, на бабу Таню — и пошла работать в кафе «Облачко». Говорят, пирожки у неё получаются почти как у бабы Тани. Почти.<br><br>Аэроград снова на высоте 50 километров. Внуки летят дальше вместе с бабкой и дедом: следующая пересадка — Юпитер, самая большая планета.', '▶ Глава 10: Юпитер', () => goChapter(10)); return; }
  if (W.ch === 10) { W.flags.ch10 = 1; stepI = STEPSC.length; W.ckpt = null; W.obj = { text: 'Свободная езда по Европе' }; save(); titleCard('ГЛАВА 10 ПРОЙДЕНА', 'Билеты на Сатурн!', 'Царь-рыба нырнула глубоко-глубоко в океан Европы и больше не трясёт лёд. Контролёр Аркадий торжественно выдал новые билеты — и сам прокомпостировал их Гошиным зубом.<br><br>Следующая пересадка — Сатурн: кольца из льда и камней, и луна Титан с метановыми озёрами.<br><br>⭐ Глава 11 «Сатурн» — скоро', 'Кататься по Европе', () => {}); return; } }
function clearMission() { if (W.rad10) { W.rad10.p.forEach((q) => W.scene.remove(q.sp)); W.rad10 = null; W.botStop = false; } if (W.fish10) { W.fish10.holes.forEach((h) => W.scene.remove(h.g)); if (W.fish10.sp) W.scene.remove(W.fish10.sp); W.fish10 = null; } run10End(); (W.waves10 || []).forEach((q) => W.scene.remove(q.m)); W.waves10 = []; if (W.holes10) { W.holes10.forEach((h) => W.scene.remove(h.g)); W.holes10 = null; } if (W.leak9) { W.leak9.forEach((q) => W.scene.remove(q.sp)); W.leak9 = null; } if (W.seed9) { W.seed9.forEach((q) => W.scene.remove(q.sp)); W.seed9 = null; } W.gust9 = null; W.fan9 = null; if (W.bolt9) { W.bolt9.rings.forEach((q) => W.scene.remove(q.ring)); W.bolt9 = null; } W.tank9 = null; if (W.l9) { W.l9.rings.forEach((q) => W.scene.remove(q.ring)); W.l9 = null; } if (W.race8) { W.race8.rings.forEach((q) => W.scene.remove(q.m)); W.race8.rocks.forEach((q) => W.scene.remove(q.ring)); W.race8 = null; } if (W.salt8p) { W.salt8p.forEach((q) => W.scene.remove(q.sp)); W.salt8p = null; } if (W.ice8) { W.ice8.vents.forEach((v) => { W.scene.remove(v.ring); W.scene.remove(v.sp); }); W.ice8 = null; } if (W.st8) { (W.st8.rocks || []).forEach((q) => W.scene.remove(q.ring)); W.st8 = null; } if (W.beam8) { W.scene.remove(W.beam8); W.beam8 = null; } if (W.boss && W.boss.rocks) W.boss.rocks.forEach((q) => W.scene.remove(q.ring)); if (typeof evacEnd === 'function') evacEnd(); W.rj = null; W.thin = 0; W.nobrake = 0; ['cans7', 'bub7'].forEach((k) => { if (W[k]) W[k].forEach((q) => q.sp && W.scene.remove(q.sp)); W[k] = null; }); W.gar7 = null; if (W.boss && W.boss.vents) W.boss.vents.forEach((v) => v.ring && W.scene.remove(v.ring)); if (W.comet6) { W.scene.remove(W.comet6); W.comet6 = null; } W.flyMode = 0; if (W.saucer) W.saucer.visible = false; ['wins', 'boxes6', 'pot6'].forEach((k) => { if (W[k]) W[k].forEach((q) => q.sp && W.scene.remove(q.sp)); W[k] = null; }); if (W.ice6) { W.ice6.picks.forEach((q) => W.scene.remove(q.big ? q.ring : q.sp)); W.ice6 = null; } W.fall = 0; W.fell = 0; if (W.hk) { W.scene.remove(W.hk.puck.mesh); W.hk = null; } if (W.gy) { W.gy.vents.forEach((v) => W.scene.remove(v.ring)); W.gy.flakes.forEach((f) => W.scene.remove(f.sp)); W.gy = null; } if (W.roof) { W.scene.remove(W.roof.sp); W.roof = null; } if (W.race) { (W.race.rings || []).forEach((q) => W.scene.remove(q.m)); W.race = null; } W.windX = W.windZ = 0; W.calm = 0; W.sleepT = 0; W.frozenT = 0; W.slow = 1; W.thief = null; W.ants = null; W.dmgBonus = 0; W.rockZone = null; W.dark2 = 0; if (W.picks) W.picks.forEach((q) => W.scene.remove(q.sp)); W.picks = null; if (W.cat) W.scene.remove(W.cat.sp); W.cat = null; if (W.wseg) { W.scene.remove(W.wseg); W.wseg = null; } if (W.dust) W.dust.forEach((q) => W.scene.remove(q.sp)); W.dust = null; }
function goChapter(n) { W.paused = true; W.needPacks(n).then(() => goChapter2(n)); }
function goChapter2(n) { clearMission(); { const s = W.st; s.fuel = 100; s.hull = s.hullMax; s.food = Math.max(4, s.food); s.ammo = Math.max(100, s.ammo); s.nerves = 100; } /* новая глава — свежий старт */ W.EN.forEach((e) => (e.dead = true)); W.boss = null; W.queen = null; W.mwave = null; bossBar(null); W.loadChapter(n); STEPSC = CHAPTERS[n]; stepI = 0; W.lastSafe = null; placeEvents(); save(); W.ckpt = JSON.parse(localStorage.getItem('bm_world') || 'null'); STEPSC[0].start(); }
W.onGameOver = function (why) { const s = st(); const stars = Math.floor((s.kills || 0) / 15) + stepI * 2; titleCard('ЭКСПЕДИЦИЯ ОКОНЧЕНА', why, `Уровень деда: ${s.lvl} · тварей повержено: ${s.kills || 0} · пройдено миссий: ${stepI}<br>Бабуля уехала отдохнуть к сестре. Вернётся к ужину — с новыми силами.`, '🔁 Снова в путь (с последней точки)', () => restart()); };
function restart() { const sv = W.ckpt || load(), c0 = W.st, keep = { lvl: c0.lvl, xp: c0.xp, need: c0.need, hullMax: c0.hullMax, kills: c0.kills, money: c0.money, parts: c0.parts, armor: c0.armor }, cw = {}, cp = {};
  for (const [k, v] of Object.entries(W.WEAP)) cw[k] = v.lv; for (const [k, v] of Object.entries(W.PERK)) cp[k] = v.lv; // прогресс деда не теряется: откатывается только задание
  W.resetCombat(); W.EN.forEach((e) => (e.dead = true)); W.st = Object.assign(fresh(), sv ? sv.st : {}, keep); W.st.dead = false; W.st.hull = W.st.hullMax; W.st.nerves = Math.max(60, W.st.nerves); if (sv) { stepI = sv.step; Object.assign(W.flags, sv.flags); } applyWeapons(cw, cp);
  const c = W.lastSafe || POI[0]; R.x = c.x + 6; R.z = c.z + c.r * 0.6; R.v = 0; R.h = Math.PI; W.st.fuel = Math.max(60, W.st.fuel); W.st.ammo = Math.max(60, W.st.ammo || 0); W.paused = false; W.boss = null; W.queen = null; W.mwave = null; bossBar(null); clearMission(); STEPSC.forEach((s) => (s.arrived = 0)); W.again = true; if (STEPSC[stepI]) STEPSC[stepI].start(); W.again = false; }
const fresh = () => ({ hull: 150, hullMax: 150, nerves: 100, fuel: 100, food: 6, ammo: 160, parts: 0, money: 150, xp: 0, need: 8, lvl: 1, kills: 0 });
function save() { try { const w = {}, p = {}; for (const [k, v] of Object.entries(W.WEAP)) w[k] = v.lv; for (const [k, v] of Object.entries(W.PERK)) p[k] = v.lv; localStorage.setItem('bm_world', JSON.stringify({ ch: W.ch, step: stepI, flags: W.flags, st: Object.assign({}, W.st, { dead: false }), w, p, x: R.x, z: R.z })); } catch (e) {} }
function load() { try { return JSON.parse(localStorage.getItem('bm_world') || 'null'); } catch (e) { return null; } }
function applyWeapons(w, p) { for (const [k, v] of Object.entries(w || {})) if (W.WEAP[k]) W.WEAP[k].lv = v; for (const [k, v] of Object.entries(p || {})) if (W.PERK[k]) W.PERK[k].lv = v; }
W.save = save; setInterval(() => W.active && !W.st.dead && save(), 15000);

/* ---------- старт экспедиции ---------- */
W.onStart = function () { W.paused = true; addShopBtn(); if (MODELS) MODELS.k_wormhead = wormGeo;
  W.initCombat().then(() => { const sv = load(); if (!sv || !sv.ch || sv.ch === 1) placeEvents();
    if (sv && (sv.step > 0 || sv.ch > 1)) { W.resetCombat(); W.st = Object.assign(fresh(), sv.st); stepI = sv.step; Object.assign(W.flags, sv.flags); applyWeapons(sv.w, sv.p); STEPSC = CHAPTERS[sv.ch || 1]; if ((sv.ch || 1) !== W.ch) W.loadChapter(sv.ch); placeEvents(); R.x = sv.x; R.z = sv.z; R.y = W.H(R.x, R.z); W.paused = false; W.ckpt = sv; if (STEPSC[stepI]) STEPSC[stepI].start(); else if (!W.flags.done || W.ch === 8 || W.ch === 9) chapterEnd(); else { W.toast(W.ch === 10 ? '🌙 Глава 10 пройдена — свободная езда по Европе. Глава 11 — скоро' : '🌙 Игра пройдена — свободная езда по Марсу'); if (W.ch === 7) setTimeout(offerS2, 2500); const fr = W.ch === 10 ? 'Свободная езда по Европе' : 'Свободная езда по Марсу'; W.obj = { text: fr }; $('wdObj').innerHTML = '🌙 ' + fr; } return; }
    W.resetCombat(); W.st = fresh(); stepI = 0;
    titleCard('ГЛАВА 1', 'Пенсия на Марсе', 'Колония «Заречная». Билет до Земли стоит 30 000 ₽. В копилке — пусто. У бабы Тани есть марсоход «Буханка-М», у деда — ружьё с солью, у кота Гоши — своё мнение.<br><br>Левый палец — руль и газ. Дед стреляет сам. Тапни по твари — он ударит её первой.', 'Завести мотор', () => {
      W.talk([['tanya', 'Ваня, просыпайся. Едем зарабатывать на билет к внукам.'], ['ded', 'Таня, я не сплю, я целюсь. Ружьё заряжено, соль крупная.'], ['gosha', 'Мяу. (Гоша занял место штурмана. Карта у него под лапой.)']], () => STEPS[0].start()); }); }); };
